package com.metaplatform.agent.runs;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant;
@Entity @Table(name="tasks") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class TaskEntity { @Id @Column(name="task_id",length=64) private String taskId; @Column(name="run_id",nullable=false,length=64) private String runId; @Column(name="parent_task_id",length=64) private String parentTaskId; @Column(name="assignee_agent",nullable=false,length=128) private String assigneeAgent; @Column(nullable=false,columnDefinition="TEXT") private String objective; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private String input; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(name="output_schema",columnDefinition="jsonb") private String outputSchema; @Column(name="permissions_ref",nullable=false,length=64) private String permissionsRef; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private String budget; @Column(nullable=false,length=32) private String status; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; }
